using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.NTF.TiposNotificacion{    [SwaggerSchema("Modelo de lectura de un TiposNotificacion")]    [GraphQLDescription("Objeto que representa un TiposNotificacion existente.")]    public class clReadTiposNotificacion    {        [SwaggerSchema("Identificador único del TiposNotificacion")]        [GraphQLDescription("Identificador único del TiposNotificacion")]        public int? TipoNotificacionID { get; set; }        [SwaggerSchema("TipoNotiicfacion")]        [GraphQLDescription("TipoNotiicfacion")]        public string? TipoNotiicfacion { get; set; } = default!;        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un TiposNotificacion")]    [GraphQLDescription("Input para crear un TiposNotificacion.")]    public class clCreateTiposNotificacion    {        [GraphQLNonNullType] [SwaggerSchema("TipoNotiicfacion")]        [GraphQLDescription("TipoNotiicfacion")]        public string TipoNotiicfacion { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un TiposNotificacion")]    [GraphQLDescription("Input para actualizar parcialmente un TiposNotificacion.")]    public class clUpdateTiposNotificacion    {        [SwaggerSchema("Identificador único del TiposNotificacion")]        [GraphQLDescription("Identificador único del TiposNotificacion")]        public int? TipoNotificacionID { get; set; }        [SwaggerSchema("TipoNotiicfacion")]        [GraphQLDescription("TipoNotiicfacion")]        public string? TipoNotiicfacion { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}